import React from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
} from 'react-router-dom';

import HeaderNav from './components/HeaderNav';
import Home from './pages/public/Home';
import ProductCatalog from './pages/public/ProductCatalog';
import './App.css';

function PlaceholderPage({ title, description }) {
  return (
    <main className="placeholder-page">
      <p className="eyebrow">CRAFTLANKA</p>
      <h1>{title}</h1>
      <p>{description}</p>
      <a className="btn-primary" href="/products">
        Explore Products →
      </a>
    </main>
  );
}

function App() {
  return (
    <BrowserRouter>
      <HeaderNav />

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/products" element={<ProductCatalog />} />

        <Route
          path="/products/:id"
          element={
            <PlaceholderPage
              title="Product Details"
              description="We will build the full product details and purchase page next."
            />
          }
        />

        <Route
          path="/artisans"
          element={
            <PlaceholderPage
              title="Meet Our Artisans"
              description="Discover the talented people behind Sri Lankan handmade crafts."
            />
          }
        />

        <Route
          path="/about"
          element={
            <PlaceholderPage
              title="Our Story"
              description="CraftLanka connects local artisans with people who appreciate handmade creations."
            />
          }
        />

        <Route
          path="/cart"
          element={
            <PlaceholderPage
              title="Your Shopping Cart"
              description="Your cart page will be implemented in the next step."
            />
          }
        />

        <Route
          path="/login"
          element={<Navigate to="/products" replace />}
        />

        <Route
          path="/signup"
          element={<Navigate to="/products" replace />}
        />

        <Route
          path="*"
          element={
            <PlaceholderPage
              title="Page Not Found"
              description="The page you are looking for does not exist."
            />
          }
        />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
